// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    Log lg;

    function setUp() public {
        lg = new Log();
        c = new W_WALLET(address(lg));
    }

    function testFuzz_property(uint96 amount1, uint96 amount2, address actor1, address actor2) public {
        vm.assume(actor1 != address(0) && actor2 != address(0) && actor1 != actor2);
        vm.deal(actor1, uint256(amount1));
        vm.deal(actor2, uint256(amount2));
        vm.prank(actor1);
        c.Put{value: uint256(amount1)}(0);
        vm.prank(actor2);
        c.Put{value: uint256(amount2)}(0);

        (, , uint v0, ) = lg.History(0);
        (, , uint v1, ) = lg.History(1);
        (, uint bal1) = c.Acc(actor1);
        (, uint bal2) = c.Acc(actor2);

        // Rule: total value recorded in the log equals the total value actually deposited
        // (observable as the sum of the holders' recorded balances).
        assertTrue(v0 + v1 == bal1 + bal2);
    }
}
